import{_ as t,o,c as a,a2 as n}from"./chunks/framework.Cd7mb1YL.js";const w=JSON.parse('{"title":"Changelog","description":"A quotation keeps its marker on the blank line, because a quotation without one there is two quotations rather than one with a paragraph break in it. Both…","frontmatter":{"title":"Changelog","order":1,"editLink":false},"headers":[],"relativePath":"changelog.md","filePath":"en/changelog.md","lastUpdated":null}'),i={name:"changelog.md"};function s(r,e,d,h,c,l){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><blockquote><p>This package&#39;s history. Mawy keeps a separate changelog for each language it ships, beside that package&#39;s own manifest, because the two version independently.</p></blockquote><h2 id="vnext-2026" tabindex="-1">vNext (2026--) <a class="header-anchor" href="#vnext-2026" aria-label="Permalink to &quot;vNext (2026--)&quot;">​</a></h2><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li><p><strong>A document cannot take the page down by being deeply nested.</strong> Containers nest a hundred deep now and no further, so a four-kilobyte file of <code>&gt; </code> repeated a couple of thousand times no longer runs the stack out. Past that depth the lines are the paragraphs they would be with no rules applied.</p></li><li><p><strong>Asking for a web font no longer tells its host which page wanted it.</strong> The request for a web font&#39;s stylesheet says <code>no-referrer</code>, including for fonts an application passes in its own <code>fonts</code>.</p></li><li><p><strong>A name a document gives something no longer reaches the page around it.</strong> Under <code>html=&quot;sanitize&quot;</code>, an <code>id</code> or an <code>&lt;a name&gt;</code> written in the document goes under <code>user-content-</code>, which is the prefix GitHub uses, so a document written for GitHub keeps working. Links the document wrote to its own names move with them.</p></li><li><p><strong>Sanitised HTML is read again before it is handed over.</strong> A tree walked and found safe can be written out as markup that parses back as a different tree, which is mutation XSS. The markup is now read until reading it again changes nothing, and markup that will not settle is drawn as the characters the author wrote.</p></li><li><p><strong>A directive named after a property every object has is a directive nobody registered.</strong> <code>:::constructor</code> was answered with something off <code>Object.prototype</code>, which React then called as a component. Names are looked up as own properties now, so <code>constructor</code>, <code>toString</code> and the rest are drawn as the characters they were written with.</p></li></ul><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><p><strong>A picture can be drawn by the application instead of fetched by the viewer.</strong> The picture is handed over whole, with the address the allowlist already checked, the alt text and the title, so an application can add a header, use its own client, serve it from a cache, or refuse it. Unset, nothing changes.</p></li><li><p><strong><code>mawy-react/server</code> draws a document on a server and ships no JavaScript for it.</strong> <code>MawyDocument</code> is a React Server Component in a framework that has them and an ordinary component to <code>renderToStaticMarkup</code> in one that does not. It leaves out the controls, the copy button on a code block, and the second render <code>sanitize</code> needs to become elements.</p></li><li><p><strong>Two viewers on one page can stop giving their headings the same anchor.</strong> <code>anchorPrefix</code> puts every name a viewer gives a heading or a footnote under a word of its own, and the links the document wrote to them move with it. Unset, which is the default, nothing changes.</p></li><li><p><strong><code>mawy-react/markdown</code> is the parser on its own.</strong> <code>parseMarkdown</code>, <code>slugify</code> and every node type in the tree, with no React and no DOM, for an application that wants a document&#39;s outline or its footnotes without drawing anything.</p></li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><p><strong>Inline code is drawn in the accent colour.</strong> The pair clears 6.1:1 on its box in the light theme and 5.5:1 in the dark one. The Flutter package draws it the same way.</p></li><li><p><strong>The footnotes name themselves to a screen reader rather than writing the word across the page.</strong> The section keeps its label, so a screen reader still finds it by name, and <code>strings.footnotes</code> is still what that name is.</p></li><li><p><strong>The status line, the split-pane arithmetic and the viewer&#39;s find are diffed against the Dart ones</strong>, as part of the parity check. Widening it found that <code>countWords</code> had never been compared on unspaced text, so <code>tool/corpus.json</code> now ends with a document of Han and kana. The new fixtures are <code>tool/scrolls.json</code> and <code>tool/finds.json</code>.</p></li><li><p><strong>The undo history has a ceiling in bytes as well as in steps.</strong> Each step is the whole document, so five hundred steps of a five-megabyte file was five gigabytes. There is a budget of about sixteen megabytes now, and whichever ceiling is reached first ends the history.</p></li><li><p><strong>A highlighter written into the JSX is fetched once rather than per render.</strong> <code>highlight={() =&gt; import(&#39;mawy-react/highlight&#39;)}</code> is a new function on every render, and the effect that asked for one depended on it. The request is made once and kept.</p></li><li><p><strong>Taking the link reference definitions off a paragraph is one pass over it.</strong> The scan starts where the last one ended, instead of handing the pattern a fresh copy of everything left.</p></li><li><p><strong>Whether a toolbar button is pressed costs the size of the answer rather than the size of the selection.</strong> Each button asks whether its command is in force every time the caret moves, and each question copied the whole selection out of the document. The wrap is read at the edges of the selection now, and the line markers a line at a time.</p></li><li><p><strong>A font is asked for when the address changes rather than on every render.</strong> The effect depended on the whole <code>fonts</code> list, which is a new array on every render. The editor also no longer rebuilds its record of the drawn document on renders that changed neither the document nor the caret.</p></li><li><p><strong>The overflow menu is drawn when it is opened, not with the toolbar.</strong> Every control it holds is already in the row, hidden for measurement, and was drawn a second time into a menu nobody had opened.</p></li><li><p><strong>Numbering the footnotes costs what the document has rather than the square of it.</strong> Each name is written down as it is given out, instead of asking every note already numbered whether it had taken the name.</p></li><li><p><strong>Finding without case sensitivity folds the document in one go.</strong> Only two characters in Unicode need character-by-character treatment, so a text with neither is folded in one call.</p></li><li><p><strong>Reading a long document does less work per character of it.</strong> The reader that tidies a document before the block rules see it slices lines out whole instead of building each one a character at a time. The tree is unchanged, and both parsers still produce the same one.</p></li><li><p><strong>The drawn document is built again only when the document changed.</strong> It is kept until the blocks or the context change, which is the boundary the viewer has had all along.</p></li><li><p><strong>Typing in <code>wysiwyg</code> costs the size of the edit rather than the length of the document.</strong> Elements that miss the caret are stepped over whole, the run on the other side of a block is stepped to rather than gathered, and the <code>beforeinput</code> and <code>paste</code> listeners are bound once instead of rebound per character.</p></li><li><p><strong>Typing with the find bar open costs the same whatever it found.</strong> The matches are cut against the lines once, in one walk down both, and each line is handed only its own.</p></li><li><p><strong>The source pane draws the part of a long document that can be seen.</strong> The coloured copy under the <code>&lt;textarea&gt;</code> is cut into chunks, and only the chunks near the view are a row per line. Nothing is left out, so the browser&#39;s own find, printing and the copy&#39;s height are unchanged, and a document under six hundred lines is drawn as before.</p></li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p><strong>A pointer capture the browser refuses no longer ends the drag on the bar between the panes.</strong> <code>setPointerCapture</code> throws for a pointer that is no longer down, and the throw came before the listeners were on. Without the capture the bar still follows the pointer while it is over it.</p></li><li><p><strong>An alert is drawn as an alert rather than as a quotation.</strong> An alert is a <code>blockquote</code>, and the quotation&#39;s rule matched it at (0,2,1) against the alert class&#39;s (0,2,0). The alert&#39;s rules are written against the element now.</p></li><li><p><strong>A quotation&#39;s last paragraph stops leaving a strip of empty box under it.</strong> The paragraph&#39;s bottom margin ran the rule down the side a line lower than the words beside it. The viewer already did this for an alert.</p></li><li><p><strong>A footnote&#39;s two links move the pane they are in.</strong> Both are <code>href=&quot;#…&quot;</code> links, which a router around the viewer is free to take. The document scrolls itself now, the way it does for the outline and for a match in the find bar, and the links stay real links.</p></li><li><p><strong>A run dragged from one place in the drawn document to another is moved rather than copied.</strong> The two input events were answered separately, so the second was measured against a document the first had not changed and the run appeared twice. They are one edit now. A drop from another application, or one held down as a copy, still only inserts.</p></li><li><p><strong>The toolbar counts the rules between its groups when it works out what fits.</strong> A group&#39;s own width leaves out the separator before it and the gaps around it, about fifteen pixels a group, so the row kept a group it had no room for. What is measured now is where each group ends.</p></li><li><p><strong>Two footnotes can no longer be given the same name.</strong> Where a document had already written out the name a slugged label would take, both got it. A name that is taken is counted past now until one is free.</p></li><li><p><strong>A document drawn on a server and picked up in a browser agrees with itself.</strong> Under <code>html=&quot;sanitize&quot;</code> the server draws the markup as characters and the browser drew elements on its first render, which is a hydration mismatch. The characters come first now and the elements on the render after.</p></li><li><p><strong>An image can be given a box to arrive into.</strong> <code>--mawy-doc-image-aspect</code> reserves the box, and <code>--mawy-doc-image-fit</code>, <code>contain</code> by default, letter-boxes a picture of a different shape rather than cutting it. Unset, which is the default, nothing changes.</p></li><li><p><strong><code>Escape</code> puts the tooltips away</strong>, and the next move of the pointer brings them back. A tooltip drawn by the stylesheet cannot hear a keystroke, so one sitting over what somebody was reading stayed there.</p></li><li><p><strong>The bar between the panes of <code>split</code> is something a finger can hit.</strong> It was five pixels and is thirteen now, with the same one pixel drawn down the middle.</p></li><li><p><strong>The status line says what it is in a word a screen reader reads.</strong> An <code>aria-label</code> on a paragraph names something that has no name to give, and most screen readers dropped it. The word is in the line now, hidden from the page and not from a reader.</p></li><li><p><strong>A choice in a toolbar menu is one tab stop, with the arrows inside it.</strong> The stop is the option already chosen, and the arrow keys, <code>Home</code> and <code>End</code> move between them, which is what <code>radiogroup</code> had been claiming. The arrows move the focus without picking, so arrowing past <code>Heading 2</code> leaves no edit behind.</p></li><li><p><strong>A toolbar menu&#39;s panel says it is a group rather than a dialog.</strong> The panel keeps none of a dialog&#39;s focus promises, and a role a screen reader acts on that the component does not honour is worse than no role. <code>aria-haspopup</code> has gone with it, and <code>aria-expanded</code> says what there is to say.</p></li><li><p><strong>A keyboard reaches the right-hand end of a wide table or a long line of code.</strong> Each scrolls sideways inside its own box, and each is a tab stop now.</p></li><li><p><strong>The interface says which language it is in.</strong> With <code>locale=&quot;ko&quot;</code> inside an English page there was no <code>lang</code> for a screen reader to go on. The toolbar, the find bar, the status line, the outline panel, the empty state and the footnotes heading carry one now. The document does not, because its language is the author&#39;s.</p></li><li><p><strong>A file dropped on the editor or the viewer is checked against the same list the picker offers.</strong> A <code>.zip</code> dropped on an editor with <code>fileDrop</code> on was read as text and became the document. The list is read generously, because platforms are unreliable about media types: an extension on the list, a media type on the list, anything called <code>text/</code>, and a file with no type at all are all taken.</p></li><li><p><strong><code>Enter</code> stops carrying a definition marker down in an editor that does not read definition lists.</strong> <code>continueList</code> takes <code>parse.definitionLists</code> now, and defaults to reading them.</p></li><li><p><strong>The status bar says the column in the same characters as the count beside it.</strong> The column was counted in UTF-16 units and the selection in code points. Both are code points now.</p></li><li><p><strong>Finding without case sensitivity reports the match where it is.</strong> A letter whose lower case is longer, such as <code>İ</code>, made the folded copy longer than the document and shifted every match after it. The folding keeps the length now, at the cost of <code>İ</code> matching only itself.</p></li><li><p><strong>A heading toggles off over a selection with a paragraph break in it.</strong> Blank lines were read as lines that are not headings, so the toggle never turned off. They are read past now and left alone, which is what every other line marker already did.</p></li><li><p><strong>Making two paragraphs a list no longer leaves an empty item between them.</strong> A blank line inside a list is left alone now, which is what the ordered list already did.</p><p>A quotation keeps its marker on the blank line, because a quotation without one there is two quotations rather than one with a paragraph break in it. Both packages, and the parity check diffs them.</p></li><li><p><strong>Deleting a word or a line on the drawn surface does something.</strong> <code>Alt</code>+<code>Backspace</code>, <code>Ctrl</code>+<code>Backspace</code> and the other multi-character deletions had no answer written for them, so the keystroke did nothing. What is deleted is the run the browser hands over on the event, which keeps word and line boundaries the platform&#39;s. A browser that offers no range still deletes nothing.</p></li><li><p><strong>Cutting on the drawn surface takes the words out of the document.</strong> It only ever copied them, because <code>beforeinput</code> refused the cut and nothing took its place. The run still reaches the clipboard, because the browser puts it there before it asks.</p></li><li><p><strong>Pasting a page with a drawing in it no longer brings the drawing&#39;s words along.</strong> An element outside HTML answers <code>tagName</code> in its own case, so <code>svg</code> matched nothing on the list of things that are not prose and a chart arrived as its axis labels.</p></li><li><p><strong>A directive&#39;s <code>attributes</code> answers for a key the document did not write with nothing.</strong> Reading a key spelled like <code>constructor</code> returned something off <code>Object.prototype</code>. The bag has no prototype now, and reading, spreading and <code>Object.entries</code> are unchanged.</p></li><li><p><strong><code>mawyHighlighter</code> no longer claims to know a language named after a property every object has.</strong> <code>```constructor</code> was answered with yes, so <code>supports</code> gave the wrong answer to a highlighter of your own as well. The block came out plain either way. The Flutter package was never affected.</p></li><li><p><strong>The bar between the panes of <code>split</code> stops when it is let go.</strong> The drag read the bar off a synthetic event after the handler returned, when React had already nulled <code>currentTarget</code>, so the listeners were never removed. A bar dragged twice moved twice as far as the hand did. The keyboard half was never affected.</p></li></ul><h2 id="_1-0-0-2026-09-02" tabindex="-1">1.0.0 (2026-09-02) <a class="header-anchor" href="#_1-0-0-2026-09-02" aria-label="Permalink to &quot;1.0.0 (2026-09-02)&quot;">​</a></h2><p>The entries below are a long list of work, and a long list is a minor version. What makes this a major is the promise that comes with the number: from here the exported API is under semantic versioning, so a name that goes away or changes shape waits for another major. Nothing exported changed shape in this release.</p><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><p><strong>The viewer can be searched too.</strong> A find button on its toolbar, <code>Ctrl</code>+<code>F</code> (<code>Cmd</code>+<code>F</code>) while it has the focus, every match marked as the query is typed and the one being stepped through marked apart — the same bar and the same colours the editor has, without the second row, there being nothing in a viewer to put anything in place of.</p><p>What it searches is the text the document <em>draws</em>, which is the whole difference between this and the editor&#39;s. <code>**bold**</code> puts six characters in the source and four on the page, and a reader looking for <code>bold</code> is looking at the page: so <code>bold</code> is found inside the bold, and <code>**</code> is found nowhere. A fenced code block is not searched — it is drawn as the highlighter&#39;s own spans, and cutting a mark into those would mean cutting every one of them — and a match cannot straddle two runs, so <code>hello</code> is not found across <code>he**llo**</code>.</p><p>The button is the <code>find</code> toolbar item and the shortcut comes with it: a viewer whose <code>toolbar</code> leaves it out leaves <code>Ctrl</code>+<code>F</code> to the browser, which is the right answer for a viewer that fills the page. Taking it is worth doing for one inside a pane of its own, which the browser&#39;s find scrolls past rather than into.</p></li><li><p><strong>Finding marks every match at once, and marks the one you are on apart from the rest.</strong> Before, the only thing on the page saying where a match was was the selection sitting on it — one match, and only after pressing next. Typing a query told you how many there were and nothing about where.</p><p>Every match is now painted as the query is typed, in a wash of yellow, with the one being stepped through in a stronger orange. Which turns the count beside the field into something you can check against the document rather than take on faith, and makes &quot;next&quot; a thing that visibly moves.</p><p>In the source pane it goes in the coloured layer under the textarea rather than into the textarea&#39;s own selection, so a match inside a heading or a link keeps the colour the highlighter gave it and gains a background. <code>--mawy-find</code> and <code>--mawy-find-current</code> are the two colours, and they are palette variables like every other colour here.</p></li><li><p><strong>The bar between the two panes of <code>split</code> is something to take hold of.</strong> Half and half is a guess about what somebody is doing, and it is wrong as often as it is right: a wide window wants more preview while reading over a draft and more source while writing one.</p><p>Drag it, or focus it and use the arrows — <code>Shift</code> for a bigger step, <code>Home</code> and <code>End</code> for the ends, <code>Enter</code> or a double-click for half and half again. It is a <code>separator</code> with a value, which is what it is, and a bar nobody can move without a pointer is a bar half the readers of an editor cannot move at all. It stops well short of either edge, because a pane pushed to nothing is a pane nobody can get back.</p><p>No prop for it, and <code>strings.divider</code> is the only thing added. Where a pane&#39;s edge sits is the same kind of thing as where a scrollbar sits — the reader&#39;s, for as long as they are looking at it — and an application with a reason to store it already has <code>value</code> and <code>onChange</code> for the thing worth storing. Below the width at which the panes stack there is no bar and nothing for it to be between. 0.5 kB gzipped on the editor and 0.1 kB on the stylesheet.</p></li><li><p><strong>A toolbar too narrow for its buttons keeps what fits and puts the rest in a menu at the end of it.</strong> What happened before was a wrap: the buttons went on to a second row and the bar did not grow, because the layout above it had made room for one. The lower row left the bar.</p><p>Whole groups at a time and from the end. The separators an application already writes are the grouping — the surface switch, then what marks up a run of text, then what makes a block of one, then the file and the palette — so reordering <code>toolbar</code> reorders what goes first, and there is no second list here saying what belongs with what. The first group never leaves.</p><p>The measuring is one layout effect and a <code>ResizeObserver</code>: every group is shown, measured and put back before the browser paints, because a group that has been taken out of the row has no width to read. Hiding a child does not change the width of the row that holds it, so the observer cannot set itself off.</p><p><code>strings.more</code> is new, and the menu is a <code>dialog</code> with the groups inside it in the order they left. 0.6 kB gzipped on the editor, and the viewer&#39;s 0.1 kB is the stylesheet it shares.</p></li><li><p><strong><code>wysiwyg</code> keeps a marker on the page until it is the block it looks like.</strong> Typing <code>#</code> used to make an empty heading, and an empty heading draws no characters at all — so the character somebody had just typed disappeared as they typed it, and somebody who wanted a <code>#</code> in a sentence had a heading to undo.</p><p>The parser is not what changed and is not what was wrong: <code>#</code> on a line of its own is an empty ATX heading, CommonMark says so in as many words, and the viewer should go on drawing one. What changed is the surface that is being typed into, which already writes a link, an image and a piece of raw HTML out as their own characters when the caret is inside them, for exactly this reason — there is nothing of the document on the page for a caret to sit in. A block written so far as its marker and nothing else is the same thing said about a whole line.</p><p><code>-</code>, <code>&gt;</code>, <code>1.</code> and <code>- [ ]</code> too, with a bullet, a bar, a number or a box left where the text went. The outermost such block is the one written out, so a list holding one empty item is the list rather than the item — a bullet drawn beside the <code>-</code> that is a drawing of it is not an improvement.</p></li><li><p><strong>The highlighter knows Dart.</strong> It is the one language this library is written in that the highlighter it ships could not colour, which showed on the documentation site: every Flutter example on it is a fenced <code>dart</code> block, and every one of them was drawn plain.</p><p>Doc comments, annotations, strings written across three quotes, and <code>void</code>, <code>dynamic</code>, <code>bool</code>, <code>int</code>, <code>double</code> and <code>num</code> as types rather than keywords — the same decision TypeScript&#39;s <code>void</code> already gets here. Every other type is caught by the capital letter, which Dart&#39;s own style guide asks for.</p><p>It is a grammar in both packages and a case in <code>tool/code.json</code>, so the parity check diffs every token the two produce over it. The entry point goes from 2.6 kB gzipped to 2.8 kB, and the viewer and the editor do not move — nothing in either reaches the highlighter unless an application names it.</p></li><li><p><strong>One more of CommonMark, and the number moved from 639 to 640.</strong> The last one about looseness, which is the question of whether a list&#39;s items are paragraphs or lines. A blank line loosens the list it is in, and the test for which blank lines count was &quot;between two of the item&#39;s own blocks&quot; — which a reference definition falls outside of, being taken off the paragraph above it before anything counts what is left. An item ending in one had a blank line with a block above it and nothing below, and the list stayed tight.</p><p>It is &quot;past the end of one of them and inside none of them&quot; now. Inside is what the old test was really for: a blank line in the middle of a nested list belongs to that list and loosens it there, and one in the middle of a fenced block is code. Neither says anything about the item holding it.</p></li><li><p><strong>One more of CommonMark, and the number moved from 638 to 639.</strong> The last of the lazy continuation, and the same rule from the other side: a lazily taken line cannot cut its paragraph short any more than it can underline it. It is there <em>because</em> the paragraph is open, so whatever it looks like once it arrives, it is that paragraph&#39;s next line.</p><p>What it looks like is the point. A container hands a lazy line over with its indentation gone, and <code> - e</code> under a list item four columns in is not a marker where it was written — three spaces is as far in as one goes — and is a marker by the time the item&#39;s paragraph sees it. It used to open a list nobody wrote.</p></li><li><p><strong>Three more of CommonMark, and the number moved from 635 to 638.</strong> All three are the lazy continuation — the line under <code>&gt; foo</code> that forgot its own <code>&gt;</code> and is part of the quotation anyway.</p><p><strong>Only a paragraph is continued that way.</strong> A line belongs to the quotation above it because there is a paragraph up there still waiting for its next line, and for no other reason: a fence the quotation opened, or code it indented four columns, is waiting for nothing, and the line below it belongs to whatever is beside the quotation rather than inside it. A quotation whose one line opens a fence, followed by an unquoted line, is an unclosed code block and then a paragraph; it used to be a code block with that line inside it.</p><p><strong>And a line taken that way is the paragraph&#39;s next line and nothing else</strong> — in particular it is not a setext underline. <code>&gt; foo</code>, <code>bar</code>, <code>===</code> is a quoted paragraph of three lines rather than a heading.</p><p>It costs 0.2 kB gzipped, in both the viewer and the editor, which is what reading a quotation&#39;s lines twice comes to.</p><p>What the quotation has open is now read as it takes its lines, a line at a time, rather than guessed from whether the last one was blank. It stops reading at the first line that opens a container of its own, because what is open inside a list inside a quotation is a question about the list and answering it there would be the block scanner written twice — so a lazy line under one of those runs the way it always has.</p></li><li><p><strong>One more of CommonMark, and the number moved from 634 to 635.</strong> A document that ends in a newline has that many lines and not one more. The reader ran once past the last character on purpose — a source of nothing at all is still one empty line — and kept the line it made there even when the newline before it had already ended a line that was written. Nowhere did that show except inside a fence the document ended before closing, where the code came out a line taller than it is.</p><p>What it cost was a blank line at the end of a <em>closed</em> code block, and it cost it in the test suite rather than in the parser: the writer that turns the tree back into HTML wrote the final newline only where the value did not already end in one, which is a rule that cannot tell a real trailing blank line from an invented one. Both halves are gone, and a fenced block inside a list item whose last two lines are blank is three lines of code again rather than two.</p></li><li><p><strong>The whole Latin-1 block of character references</strong>, which is four more of CommonMark and takes the number from 630 to 634. <code>&amp;ouml;</code>, <code>&amp;eacute;</code>, <code>&amp;szlig;</code>, <code>&amp;frac12;</code> — what a document written in a European language reaches for, and what an author who typed <code>Fr&amp;ouml;hlich</code> meant a word by. Ninety-seven names, read everywhere the specification asks for a reference: in a destination, a title, a reference definition&#39;s label and a fence&#39;s info string.</p><p>It costs 0.6 kB gzipped, and the viewer was 22.8 kB when this landed. The table is still the names documents actually use rather than all 2,231 of HTML5&#39;s, which would be a hundred kilobytes on every page for <code>&amp;DifferentialD;</code>.</p></li><li><p><strong>One more of CommonMark, and the number moved from 629 to 630.</strong> A numeric character reference is at most seven digits, or six in hexadecimal, which is the specification&#39;s own limit. <code>&amp;#87654321;</code> was being read as a reference to a code point that does not exist and drawn as U+FFFD; it is not a reference at all, and is the eleven characters somebody typed.</p></li><li><p><strong>Two more of CommonMark, and the number moved from 627 to 629.</strong></p><p><strong>A no-break space is not whitespace</strong>, as the specification counts it — the five characters it means by the word are space, tab, newline, form feed and carriage return, and a regular expression&#39;s <code>\\s</code> is every Unicode space there is. So <code>[link](/url\\u00a0&quot;title&quot;)</code> has a destination of <code>/url\\u00a0&quot;title&quot;</code> and no title, because nothing separated the two. The emphasis rules still use <code>\\s</code>, and correctly: those are written in terms of Unicode whitespace.</p><p><strong>A thematic break wins over a list item</strong> inside a list as much as outside one. <code>* * *</code> on the second line of a list of <code>*</code> items was an item with two more bullets in it, and is a rule that ends the list.</p><p>The viewer is 0.1 kB larger for the two, at 22.3 kB gzipped.</p></li><li><p><strong>Two more of CommonMark, and the number moved from 625 to 627</strong> — both about a link inside an image&#39;s description. Closing a link deactivates the <code>[</code> openers to its left, which is what stops a link nesting inside a link; it was deactivating the <code>![</code> openers as well, so <code>![foo [bar](/url)](/url2)</code> was a sentence with a link in it rather than an image whose alt text is <code>foo bar</code>. An image&#39;s description is allowed to hold a link, and only the link openers are switched off now.</p></li><li><p><strong>Four more of CommonMark, and the number moved from 621 to 625</strong> — all four about what a link reference definition&#39;s label may be written as.</p><p>A <strong>label may run over more than one line</strong>, which is what <code>[Foo\\n bar]: /url</code> is, and it is found by <code>[Baz][Foo bar]</code> because a label is folded to one space before it is looked up. A label <strong>may not hold an unescaped bracket</strong> of either kind, so <code>[ref[]: /uri</code> is a paragraph rather than a definition that nothing can refer to. A label of <strong>nothing but whitespace</strong> is not a label, and the line it is on stays the paragraph it was rather than being taken off and dropped.</p><p>And an <strong>underline over nothing but definitions is not an underline</strong>. <code>[foo]: /url</code> followed by a line of <code>=</code> was losing that line entirely; a definition is not something a setext heading can be made out of, so the <code>=</code> is the first line of the paragraph that follows.</p></li><li><p><strong>Three more of CommonMark, and the number moved from 618 to 621</strong> — all three about reading a tag more carefully than the parser was reading one.</p><p>An <strong>attribute name</strong> is now the specification&#39;s own rule — a letter, <code>_</code> or <code>:</code> and then letters, digits, <code>_</code>, <code>.</code>, <code>:</code> and <code>-</code> — rather than &quot;anything that is not a space or a quote&quot;. A line reading <code>&lt;a h*#ref=&quot;hi&quot;&gt;</code> is a sentence about a tag, and was being drawn as one; so was a tag whose second line began <code>bim!bop</code>, since the name that could not be a name was being taken for one.</p><p>And <strong><code>&lt;!--&gt;</code> and <code>&lt;!---&gt;</code> are comments in their own right</strong>, tried before the general form. Without that, <code>foo &lt;!--&gt; foo --&gt;</code> was one comment running to the closing <code>--&gt;</code> rather than a comment followed by text.</p></li><li><p><strong><code>wysiwyg</code> is on the default <code>modes</code> list</strong>, and first on it. It was left off at 0.1.0 because two things on that surface did not work — a link&#39;s destination could not be typed and raw HTML being drawn could not be edited — and both are gone: whatever the caret is inside is written out as the characters it was written with. An application that would rather not offer the surface leaves it out of <code>modes</code>, the way it says anything else about the switch.</p></li><li><p><strong>The status bar&#39;s counts are their own module</strong>, <code>src/internal/status.ts</code>, rather than functions inside the component that draws them — which is what lets the parity check diff them against the Dart ones. Nothing about the numbers changed; a count written twice is a count that reports two different answers for the same document the first time nobody is comparing them.</p></li><li><p><strong>Raw HTML is editable on the <code>wysiwyg</code> surface</strong>, under <code>sanitize</code> and <code>raw</code> as well as under <code>escape</code>, and it is editable the same way a link&#39;s destination is: markup the caret is inside is written out as the characters it was written with, and drawn back as markup when the caret leaves. That was the last thing the surface could not do — what <code>dangerouslySetInnerHTML</code> puts on the page is markup React does not know the inside of, so there was nothing in the drawn form for a caret to be inside. Written out, there is, and every rule the surface already has applies to it unchanged.</p><p>The writing-out now happens only while the editor has the focus. A document that opens with a link would otherwise show its brackets to a reader who has not touched it, and &quot;the thing the caret is inside&quot; is not a question an editor nobody is typing in has an answer to. The editor rather than the drawn surface, because pressing a button on the toolbar takes the focus out of the document and the caret it is about to act on is still the caret.</p></li><li><p><strong>Six more of CommonMark, and the number moved from 612 to 618</strong> — all six about which lists are <em>loose</em>, which is the difference between an item&#39;s text sitting on the line and sitting in a paragraph of its own with space around it.</p><ul><li><strong>An item with nothing in it does not make its list loose.</strong> <code>- foo</code>, <code>-</code>, <code>- bar</code> is three tight items; the middle one being empty was being read as a blank line after it.</li><li><strong>An item may begin with at most one blank line.</strong> <code>-</code> followed by a blank line and then an indented paragraph is an empty item and a paragraph beside the list, rather than an item holding the paragraph.</li><li><strong>A blank line loosens the list it is in rather than every list around it.</strong> A blank line between two blocks inside a nested item was making the item&#39;s grandparent loose too, which put a <code>&lt;p&gt;</code> around every item at every level above it.</li></ul><p>Both parsers, and the parity trees are identical.</p></li><li><p><strong>The highlighter is diffed against the Dart one</strong>, over <code>packages/flutter/tool/code.json</code>, as part of the parity check. <code>src/highlight.ts</code> and <code>lib/src/highlight.dart</code> are one grammar written twice and they drift for exactly the reason the two parsers do; nothing in this package changed, and now nothing can change in it alone.</p></li><li><p><strong>Seven more of CommonMark, and the number moved from 605 to 612.</strong> Four kinds of thing the parser was reading as the characters they were written with rather than as what they say:</p><ul><li><strong>A destination and a title read their escapes and their character references</strong>, inline and in a reference definition alike — <code>[a](/bar\\*)</code> is <code>/bar*</code>, and <code>[a]: /u &quot;ti\\*tle&quot;</code> is <code>ti*tle</code>. The inline scan already took the backslashes off; the definition kept them, so the same link meant two things depending on where it was written.</li><li><strong>So does a fence&#39;s info string.</strong> <code>```foo\\+bar</code> is <code>language-foo+bar</code>.</li><li><strong>A backtick fence whose info string holds a backtick is not a fence.</strong> <code>``` ```</code> on a line of its own is a code span with a space in it, and reading it as an empty code block swallowed the rest of the document until something closed the fence.</li><li><strong>An escaped bracket is a bracket a shortcut reference&#39;s label may hold.</strong> <code>[Foo*bar\\]]</code> is one label rather than a failed reference.</li></ul><p>The label a reference is <em>looked up</em> by is deliberately not unescaped, which is the specification and not an oversight: <code>[foo\\!]</code> and <code>[foo!]</code> are two labels, and both sides of the lookup fold the characters as written so the two cannot disagree.</p><p>Five deviations were reclassified rather than fixed. An empty destination is a decision: <code>&lt;a href=&quot;&quot;&gt;</code> is a control that does nothing, and this library&#39;s answer for a destination it will not follow is to draw the words the author wrote. Four more are <code>&amp;ouml;</code> and <code>&amp;auml;</code>, which are outside the character reference table this package carries.</p></li><li><p><strong>A link or an image the caret is inside is written out as its own characters</strong> on the <code>wysiwyg</code> surface, destination and all, and drawn back as itself when the caret leaves.</p><p>This is the destination becoming editable, which it was not. A drawn <code>&lt;a&gt;</code> puts its words on the page and never its <code>(url)</code>, so there was nowhere on the page for an address to be and nothing for a keystroke to land on — the toolbar&#39;s <code>[](url)</code> arrived with a placeholder that could not be typed over, and an existing link&#39;s destination could only be changed on the source surface. Written out it is the source one character for one, and every rule the surface already has applies to it unchanged: there is no link editor, no popover and no second way to type.</p><p>It follows the caret rather than a mode, and only where the whole selection sits inside one link — a range dragged across half a document turns nothing into markup under the pointer. What is revealed is marked rather than disguised, because text that has stopped being a link and started being the text that makes one is a difference worth being able to see.</p></li><li><p><strong>A print stylesheet.</strong> A viewer on paper is the document and nothing else — the toolbar, the outline, the status bar, the find box and a footnote&#39;s link back to where it was mentioned are all things to press, and paper cannot be pressed. Three more things change because a page is not a screen: a viewer given a height is as tall as its document instead of printing one boxful, the palette goes dark-on-light whatever the reader chose, and a link&#39;s destination is written out after it. In the editor the drawn document prints — <code>split</code> drops the source pane, and <code>plain</code> prints the source as text rather than as a <code>&lt;textarea&gt;</code>, which would put only its own boxful on the page. Nothing to switch on: it is <code>@media print</code> in the stylesheet that was already imported.</p></li><li><p><strong>An accessibility pass, run by <a href="https://github.com/dequelabs/axe-core" target="_blank" rel="noreferrer">axe</a> rather than by opinion</strong>, over every surface in both palettes — the viewer with a document and as the file picker, all four editor modes, the outline open, a menu open, find and replace open. Four things it found, all fixed:</p><ul><li><strong>A task list&#39;s checkbox had no name.</strong> It was announced as &quot;checked, checkbox&quot; and nothing else, with the one thing worth knowing — what is done — sitting beside it as text. The item&#39;s first line is now the name.</li><li><strong>The editing surface was an <code>&lt;article role=&quot;textbox&quot;&gt;</code>.</strong> ARIA does not let a document section be a textbox, so it is a <code>&lt;div&gt;</code> now. The viewer&#39;s drawn document is still an <code>&lt;article&gt;</code>, where it is one.</li><li><strong>The link back from a footnote was a colour and nothing else</strong>, inside running text. It is underlined.</li><li><strong><code>--mawy-fg-subtle</code> did not meet WCAG AA</strong> against either background: <code>#8b8b96</code> is 3.4:1 on white and 3.1:1 on the sunken grey. It is <code>#70707b</code> in the light palette and <code>#87879a</code> in the dark, both over 4.5:1 everywhere they are used — and the Dart palette moved with it, because the two are one palette.</li></ul></li><li><p><strong>A size budget, and a stylesheet with its prose taken out.</strong> <code>npm run size</code> bundles the published files for real and compares the result to <code>size-budget.json</code>, which CI now fails a change for going over. What it measures is what a consumer&#39;s bundler produces: React external because an application already has it, <code>lucide-react</code> counted because it arrives with this, and gzip because every server on the path compresses.</p><p>Gzipped, that is <strong>22.2 kB for <code>MawyViewer</code>, 38.0 kB for <code>MawyEditor</code></strong>, 2.6 kB for the highlighter and 5.5 kB for the stylesheet. The fifteen kilobytes between the first two are the editor falling out of a page that only reads documents — the toolbar, the undo history, the paste pipeline, every <code>contenteditable</code> surface — which is the number the package is shaped around and the one nothing but a real bundle can see.</p><p>The stylesheet is now minified on its way into <code>dist/</code>. Two fifths of <code>styles.css</code> is prose written for somebody reading the source, and a reader of a page was paying 3.7 kB gzipped for comments they cannot see; <code>src/styles.css</code> is still the file to read and to edit, and what ships is the same rules in the same order. The build checks the two things that would make that a bad trade: every <code>--mawy-*</code> custom property still declared, and every <code>:where()</code> still a <code>:where()</code>, because those are the resets and a reset that gained specificity is one that starts beating the page it was dropped into.</p><p>Also checked there, because it is the failure a bundler hides: Node&#39;s own resolver, on every entry point the package claims to have. A bundler forgives a specifier that a server render does not.</p></li><li><p><strong>How much CommonMark, as a number.</strong> The specification&#39;s own 652 examples are run at the parser on every change, and it answers 605 of them. The other 47 are written down in <code>test/internal/markdown/commonmark.test.ts</code>, one line each with the reason it is there, so the list can only get shorter deliberately — and a fix that is not recorded fails the same test.</p><p>Three of them are a decision rather than a shortfall: every URL is checked against a scheme allowlist, so <code>&lt;made-up-scheme://foo&gt;</code> is drawn as the words the author wrote rather than as a link. The rest are edges — a tab inside a list item, a character reference in a link destination, a list counted loose where the specification counts it tight, a fence whose info string holds a backtick.</p><p>The library renders to React elements and has no HTML serialiser to measure, so the test has one of its own in <code>test/support/commonmark.ts</code>. It is a test file rather than something shipped, and the safety story is unchanged: there is still nothing between a document and the page that is a string of markup.</p></li><li><p><strong>Directives — a way for a document to carry a construct this package does not know about.</strong> The parser reads a shape and stops there: <code>:::name[label]{key=value}</code> … <code>:::</code> around blocks, <code>::name[label]{attrs}</code> on a line of its own, and <code>:name[label]{attrs}</code> inside a sentence. What each one <em>means</em> is the application&#39;s, through <code>directives</code>:</p><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MawyViewer</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> value</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{document} </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">directives</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ callout: Callout, youtube: YouTube }} /&gt;</span></span></code></pre></div><p>A component is handed the name, whatever was written in <code>{…}</code> — with <code>{#id}</code> arriving as <code>id</code>, <code>{.a .b}</code> as <code>class</code> and a bare name as a flag — the <code>[label]</code> already drawn, a container&#39;s blocks already drawn, the range it was written at and the characters it was written with. Which keeps the safety story exactly where it was: the application composes React elements, and no markup string is on the path from the document to the page. <strong>A name nobody registered is drawn as the characters it was written with</strong>, the same answer raw HTML gets under the default <code>html</code> policy, because a viewer that was never told what a construct means should show what the author wrote rather than quietly lose it — and on the <code>wysiwyg</code> surface those characters <em>are</em> the source, one for one, so an unhandled directive is editable exactly where it was typed.</p><p>The syntax is the generic directives proposal&#39;s, which is what <code>remark-directive</code> reads, so a document written for one is read by the other. Two rules here are narrower than that extension&#39;s, and both are about not changing what an existing document already said: the colons must be followed immediately by the name, so <code>::: tip</code> with a space is the paragraph it always was; and an inline directive must carry a label or attributes, so <code>Note:</code> and <code>12:30</code> and <code>:warning:</code> stay what they are.</p><p>The Dart parser reads the same syntax into the same tree, and <code>tool/parity.dart</code> diffs the two over the awkward cases and every Markdown file in the repository, as it does for everything else the parser reads.</p></li><li><p><strong><code>MawyDirectives</code>, <code>MawyDirectiveProps</code>, <code>MawyDirectiveKind</code> and <code>MawyRange</code></strong>, exported from <code>mawy-react</code> and <code>mawy-react/types</code> like the rest of the vocabulary.</p></li><li><p><strong>A Markdown file in, and out.</strong> <code>open</code> reads one into the editor and <code>save</code> writes the document back — <code>Mod</code>+<code>S</code> as well, because the browser&#39;s own <code>Mod</code>+<code>S</code> saves the page and that is never what somebody writing in an editor meant by it. Both are on the toolbar, before <code>colorScheme</code>.</p><p>Without <code>onSave</code> the text is handed to the browser as a download: an anchor with a <code>download</code> on it rather than the File System Access API, which only Chromium has — a save that works in one browser and silently does nothing in another is worse than one that always does the same thing. <code>onSave(value, name)</code> takes it over entirely, which is what an application saving to a server wants instead.</p><p>The name is the opened file&#39;s, or <strong>the document&#39;s first heading</strong> with the characters no filesystem will take dropped, or <code>document.md</code>. <code>open</code> has no shortcut on purpose: the browser&#39;s own <code>Mod</code>+<code>O</code> is a reasonable thing to leave alone, and opening a file is a rare and deliberate act.</p><p><strong>A file dropped on the editor is still an image, never a document.</strong> The drop is already how an image gets in, and replacing a document somebody has been writing because a file landed on it is how work is lost.</p></li><li><p><strong><code>&#39;open&#39;</code> and <code>&#39;save&#39;</code> on the editor&#39;s toolbar</strong>, and <code>accept</code> beside them for what the picker offers.</p></li><li><p><strong>Find and replace, on the source surface.</strong> <code>Mod</code>+<code>F</code> opens a bar over the source and the toolbar&#39;s new <code>find</code> button does the same; <code>Enter</code> and <code>Shift</code>+<code>Enter</code> walk the matches, <code>Escape</code> closes it and gives the focus back to the document. Whatever was selected is already in the box when it opens, as long as it was on one line. Replace and replace all are on the second row, and replace all is one pass over the document as it was, so replacing <code>a</code> with <code>aa</code> does not find its own replacement for ever.</p><p>It exists because the browser&#39;s own find cannot reach here: <strong>no browser searches the text inside a <code>&lt;textarea&gt;</code></strong>, and the source surface is one. Everywhere else in this library a thing the platform already does is left to the platform, and this is the place the platform does not.</p><p><strong>Plain text, never a regular expression.</strong> A Markdown document is full of <code>*</code>, <code>[</code>, <code>.</code> and <code>+</code>, and a find box that quietly compiled <code>(</code> into a syntax error is one a writer cannot trust with a document. Case sensitivity is the switch that is there instead, which is the one people reach for.</p></li><li><p><strong><code>&#39;find&#39;</code> is on the editor&#39;s toolbar</strong>, before <code>colorScheme</code>, and so is on the list <code>toolbar={true}</code> draws. It is the first control there that is not a formatting command; its shortcut works whether or not the button is drawn, like every other one.</p></li><li><p><strong><code>Tab</code> indents the source, and <code>Escape</code> is the way out.</strong> <code>Tab</code> puts two spaces in where the caret is and <code>Shift</code>+<code>Tab</code> takes them back; anything <em>selected</em> moves the lines it touches and stays selected, so it can be pressed again. Two spaces rather than four because that is a Markdown fact — a nested item has to clear its parent&#39;s marker, which under <code>- </code> is two columns, and four would be an indented code block the moment the list above it ends.</p><p>A textarea that swallows <code>Tab</code> is a keyboard trap, so the trap is opened rather than avoided: <strong>press <code>Escape</code>, then <code>Tab</code>, and the focus moves on.</strong> Anything else typed arms indentation again. It is the rule CodeMirror, Monaco and GitHub&#39;s editor all use, and the surface says so through <code>aria-describedby</code>, because a way out nobody is told about is a way out that does not exist for the person who needed it. The drawn document does not capture <code>Tab</code> at all — there is no trap there to open.</p></li><li><p><strong><code>linkTarget</code>, and a link opens in a new tab by default.</strong> <code>&#39;blank&#39;</code> puts <code>target=&quot;_blank&quot;</code> and <code>rel=&quot;noopener noreferrer&quot;</code> on every link the document wrote; <code>&#39;self&#39;</code> is for an application showing a document <em>as</em> its page.</p><p>A new tab is the default because of where this component usually is: a viewer is a piece of a page rather than the page, so a reader who follows a link out and comes back should find the document where they left it — and in an editor, what is behind that link is unsaved work. A footnote&#39;s number and the arrow back from it point at the same page and are unaffected either way. <code>MawyEditor</code> takes it too, for the preview and the drawn surface.</p><p>The Flutter package has no counterpart and will not: what opening a link means is <code>onLinkTap</code>&#39;s whole subject there, and where it opens is part of what an application answers with.</p></li><li><p><strong><code>fileDrop</code> on the editor: a Markdown file dropped on it opens as the document.</strong> Off by default, because replacing a document somebody has been writing because a file landed on it is how work is lost and <code>open</code> is the control that does it on purpose. On, for an editor that starts empty and is a place to bring a file <em>to</em> — the playground on this site is one, and has it on.</p><p>With it on, an empty preview stops saying there is nothing here and offers the picker instead: the viewer&#39;s own empty state, in the pane the document is going to appear in. A dropped image is still an image wherever <code>onUploadImage</code> is given, and the drop is still the editor&#39;s whichever pane it lands in — one answer for the whole component rather than two that have to agree.</p></li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><p><strong>A click in the preview no longer moves the caret in the source.</strong> It was the other direction of the question the scrolling asks — a place on the page, read back as a place in the document — and as a piece of arithmetic it worked. As a behaviour it was one answer too many: <code>wysiwyg</code> is the surface that edits the drawn document, and a <code>split</code> whose right-hand pane also edits is two answers to where the writing happens. A preview is a preview, and now behaves like the page it is.</p><p>The machinery it was built on is untouched and still in use — <code>caretFromPoint</code> and <code>sourceAt</code> are what put a dropped image where the pointer let go of it, and what the drawn surface reads every keystroke through.</p></li><li><p><strong>The headings panel is called &quot;Contents&quot;.</strong> &quot;Outline&quot; is what the thing is to whoever wrote it and not what a reader is looking for: a list of a document&#39;s headings, in order, to jump from. The Korean has always said 목차, which is this word. <code>&#39;outline&#39;</code> is still the name of the toolbar item and the class on the panel, because those are an application&#39;s API and renaming them would cost every consumer a line to save this package a word.</p></li><li><p><strong>The status bar is the height the Flutter package&#39;s is.</strong> It was two pixels taller, and for a reason worth writing down: <code>.mawy-root</code> sets a line height of 1.5 because a document is prose, and a strip of counts under an editor is not prose. The number is written down on the bar now rather than inherited, and it is the number the other package&#39;s row is drawn at.</p></li><li><p><strong>Two of the library&#39;s own sentences say what they mean.</strong> The veil over the editor while a file is being dragged said &quot;Drop to add&quot;, which is an instruction with the object left out; it says what will be added now. And the source surface&#39;s placeholder said &quot;Write in Markdown&quot; — a reader looking at an empty editor knows what it takes, and what they want to know is that this is where the typing goes.</p></li><li><p><strong>A button says its name in this library&#39;s own tooltip rather than the browser&#39;s.</strong> <code>title</code> waits about a second before it appears, so the name of an icon was a thing a reader had to decide to wait for; and it is drawn by the operating system, so a toolbar in a dark theme grew a light chip in a system font. This one appears the moment the pointer is on the button and is drawn in the same palette as everything else. It is a pseudo-element on the control, so there is nothing to mount and nothing to leave behind, and <code>aria-label</code> is still what names the button.</p><p>A <code>title</code> written by the <em>document</em> — <code>[words](url &quot;a title&quot;)</code> — is untouched. That is the author&#39;s text and not the library&#39;s chrome.</p></li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p><strong>The document is focusable by a click, so a keystroke has somewhere to land.</strong> It is not a <code>Tab</code> stop and does not draw a focus ring; the whole of what it changes is that <code>Ctrl</code>+<code>F</code> in a viewer somebody has just clicked into reaches that viewer.</p></li><li><p><strong><code>Enter</code> in the find field goes to the next match instead of handing the document the focus.</strong> It went to the next match too — but it took the focus with it, so the second <code>Enter</code> was a newline typed into the document, and every keystroke after that was an edit somebody had asked for a search.</p><p>The selection still moves to the match, and the document still picks up from there the moment the bar is closed. What it no longer does is take the focus while the bar is open, which is what the marking above is for: the match is shown where it is rather than shown by being selected, and the field the query is being typed into keeps the keyboard.</p></li><li><p><strong>A file dropped on the editor no longer takes the page away.</strong> A dropped file is an image and never a document, which is the rule and stays the rule — but a file the editor would not take was left to the browser, and a browser given a file it was not stopped from taking opens it as a page. The document, the undo history and the caret went with the tab, which is the exact loss the rule exists to prevent.</p><p>Any file dragged over the editor is the editor&#39;s now. An image lands where the pointer let go of it and everything else is refused with a line under the document saying so, and saying that <code>open</code> is the control that does what was being asked for. A run of text dragged in from another window is not a file, is not claimed, and is still the surface&#39;s own business.</p></li><li><p><strong>A viewer that cannot be given a document does not offer to open one.</strong> <code>value</code> with no <code>onValueChange</code> is an application saying the document is its own, and a file chosen there has nothing to become — so the picker was a button that did nothing, and it was the one the editor&#39;s preview drew over an empty document: an &quot;Open a Markdown file&quot; panel inside an editor, with a file picker that could not open a file.</p><p>The empty state says there is nothing here yet, the button under it is not drawn, the toolbar&#39;s <code>open</code> is disabled, and a drop is not claimed. <code>strings.emptyNothing</code> is new, and so is <code>strings.dropNotDocument</code> for the line the editor writes.</p></li><li><p><strong>The entry pressed in the headings panel is the one that stays marked.</strong> Following an entry is a smooth scroll and a smooth scroll passes over every heading between here and there, so the mark walked down the panel with it and settled on whichever heading was at the top when it stopped. That is not always the one that was pressed: the last heading of a document cannot reach the top of a box taller than what is under it, and a short section under a long one is passed straight through.</p><p>What was pressed is not in doubt, so it is no longer measured. The measuring starts again at the next wheel, touch, key or press inside the document — the reader saying they have gone somewhere of their own — and a wheel over the panel is not one of those, because reading the list of headings is not leaving the one you chose.</p></li><li><p><strong>The mark beside the current heading is a rule and not a bracket.</strong> It was an inset shadow, which follows the corner radius the focus ring needs and turns two pixels of rule into three sides of a box. Its own element now, so the radius stays where it is useful.</p></li><li><p><strong>The toolbar is the same height in every mode.</strong> A component given a height is a column of flex items and a flex item shrinks, so in the surfaces whose body wants more room than there is — the drawn document, <code>split</code>, <code>preview</code> — the bar was being squeezed onto its <code>min-height</code> and springing back in <code>plain</code>, which does not. Three pixels, and they moved every time the surface switch was pressed, which is the control immediately under them.</p><p>The find bar and the status bar were the same shape of thing and are fixed with it. Chrome is not what a layout should take its room from.</p></li><li><p><strong>A menu shuts when a value is picked in it.</strong> The theme, the typeface and the column width all changed the document and left the panel standing over it — a menu still open on top of the thing it has just changed is a menu hiding the answer to the question it was asked. The focus goes back to the button it came from, the way it already did on Escape.</p><p>A slider is not a value being picked and does not shut: a size is arrived at by moving it, and a panel that closed on the first step would have to be reopened for the second. That is the split the Flutter package already made, and now both make it.</p></li><li><p><strong><code>preview</code> is the same width as every other surface.</strong> The rule down the preview&#39;s leading edge is there to separate it from the source beside it, and in <code>preview</code> there is no source beside it — so the pane was a pixel narrower than the others and the box read as shifting when the surface switch was pressed. The rule belongs to <code>split</code>, and now says so.</p></li></ul><h2 id="_0-1-0-2026-08-31" tabindex="-1">0.1.0 (2026-08-31) <a class="header-anchor" href="#_0-1-0-2026-08-31" aria-label="Permalink to &quot;0.1.0 (2026-08-31)&quot;">​</a></h2><p>The first release. Everything in it is new, so each entry says what a thing is rather than what it became.</p><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong><code>MawyEditor</code></strong> — the Markdown source, a live preview, and a switch between them. <code>plain</code> edits the source as text, <code>preview</code> shows the rendered document, <code>split</code> shows both, and <code>modes</code> decides which of those the switch offers. Every surface is a view of one string, so nothing is re-serialised on the way between them.</li><li><strong>The <code>wysiwyg</code> surface, in part.</strong> The document is drawn and edited where it is drawn: typing and deleting anywhere there is text to type in — a paragraph, a heading, a list item, a quotation, a table cell, a code block — splitting a block with <code>Enter</code>, joining two with <code>Backspace</code> at the start of the second, a hard break on <code>Shift</code>+<code>Enter</code>, replacing a selection, and every command on the toolbar. There is no second model behind it and there is no DOM-to-Markdown serialiser — every keystroke is refused, turned into an edit to the Markdown, and the document is drawn again from what the Markdown became. Edits land on the drawn character rather than the written one: the caret after <code>bold</code> in <code>**bold**</code> has an asterisk in front of it in the file and a <code>d</code> in front of it on the page, and <code>Backspace</code> there takes the <code>d</code>. An input method is the one thing that cannot be refused, and is handled the other way round: a composition is left entirely alone, and when it ends the run of text it changed is compared with what it said before and the difference goes into the Markdown at the place that run came from — because refusing a composition is refusing the composition, and Korean is composed a jamo at a time. <code>Enter</code> is a different thing in every container it is pressed in — a new list item with the marker carried down, another <code>: </code> under a definition for the same reason, a blank quoted line to end a quoted paragraph, one newline inside a code block, and nothing at all in a table, where a row is a line and there is nowhere in the file for a second one. <code>Backspace</code> at the start of a block joins it to the one before, except across a table cell or a code fence, which would be eating the pipe or the fence. An image and a hard break come out in one piece. A caret the page has nowhere to draw is remembered where it meant to be — the whitespace at the end of a line is in the file and drawn nowhere, and without that <code>One two</code> could not be typed a word at a time. Raw HTML being <em>drawn</em> rather than shown is the one place an edit is refused — it reached the page through <code>dangerouslySetInnerHTML</code> and React could not put it back — and the surface is not on the default <code>modes</code> list — an application asks for it by name while it is this new.</li><li><strong>The shorthand typed at the start of a line becomes the formatting it is shorthand for</strong>, on the drawn document, where it was typed. Most of that is not a feature and is worth saying so: the document is drawn again from the Markdown after every keystroke, so <code># </code> at the start of a paragraph <em>is</em> a heading the moment the space lands, and <code>- </code>, <code>1. </code>, <code>&gt; </code> and <code>- [ ] </code> are the same story. Two are written down, and they are the two where the marker changes the meaning of text nobody is typing. Three backticks open a fence and a fence runs until one closes it — so a fence is opened <em>closed</em>, the caret between the two and whatever was on the line inside, carrying a list item&#39;s or a quotation&#39;s own prefix onto the lines it adds. A thematic break has no text in it and a caret left on one has nowhere on the page to be — so <code>---</code> is given a blank line under it to carry on typing on, and is left alone under a line that is still going, where it is that paragraph&#39;s underline rather than a break. Inside a code block none of it happens, because everything in there is the characters it is.</li><li><strong>Images, three ways in.</strong> The toolbar&#39;s image button writes <code>![](url)</code> with the destination ready to type over — the link command with a <code>!</code> in front of it, and the same rules about which half a selection becomes. An image pasted or dropped as part of a web page arrives as the URL it already had, which is not an image feature at all but markup being read as markup. And a <em>file</em> — a screenshot on the clipboard, an image dragged in from the desktop — goes wherever <code>onUploadImage</code> says: it is called once per file and answered with the URL to write, or with <code>{ url, alt, title }</code>; the file&#39;s own name, without its extension, is the description otherwise. Without that prop a dropped file does nothing and is not even refused, because there is nowhere for the bytes to go and quietly turning a two-megabyte screenshot into a <code>data:</code> URI inside somebody&#39;s document is not a decision a text editor should make. A drop lands where the pointer let go of it and a paste lands at the caret; several files at once are one upload after another and then one edit, so undo takes back the thing that was done rather than the last file of it.</li><li><strong>The preview in <code>split</code> scrolls to the block rather than to the fraction.</strong> Whichever line is at the top of the source decides which block is at the top of the preview, and the positions in between run straight from one block to the next. The fraction of the way through a file is not the fraction down the page — a fenced code block is sixty lines of source and sixty lines of page, an image is one line of source and half a screen — and the further those two get apart the further the preview is from whatever is being typed.</li><li><strong>A click in the preview puts the caret on the same word in the source.</strong> On the word, not on the paragraph: clicking the middle of a bold phrase puts the caret in the middle of it, between the asterisks. Neither pane is scrolled to do it, since in <code>split</code> the two are already showing the same part of the document. Links, checkboxes and a code block&#39;s copy button keep their own click, and a click that ended a text selection is left as a selection.</li><li><strong>A source surface built on a real <code>&lt;textarea&gt;</code></strong>, with a coloured copy of the same text laid exactly underneath it. That keeps the IME, the mobile keyboard, spellcheck and every platform text gesture — none of which is worth losing for syntax colouring. The two layers share one set of layout properties, and the line-number gutter is the same grid rather than a second stack of rows, so numbers stay level with soft-wrapped text.</li><li><strong>A syntax highlighter for the source</strong>, which is not the parser and is deliberately approximate: a line being typed is half-written most of the time, and a highlighter that waited for <code>**bold</code> to close would flicker on every keystroke.</li><li><strong>Formatting commands, each with a keyboard shortcut</strong> — bold, italic, strikethrough, code, link, images, headings, quotations, three kinds of list, code blocks and rules. All of them toggle, markers replace each other rather than stacking, and <code>Enter</code> carries a list marker down and takes it away again on an item still empty. Edits go in through the browser&#39;s own insertion command, which leaves the caret, the scroll and any composition in progress where they were.</li><li><strong>What is on the clipboard as HTML arrives as Markdown</strong>, on both surfaces: a section of a web page pasted into either one has its headings as hashes, its links as links and its list as a list. A clipboard with nothing but text on it is left to the browser, whose own paste is right and keeps the caret, the scroll and the run of undo where they were. This is not the renderer run backwards — markup from somewhere else is read once for what can be made of it and nothing round-trips through it, so it is allowed to be lossy and is. Every URL goes through the same check a Markdown link gets. Inside a code block a paste is the plain text and nothing else.</li><li><strong>Undo, over the document rather than over a surface.</strong> <code>Mod</code>+<code>Z</code> goes back, <code>Mod</code>+<code>Shift</code>+<code>Z</code> and <code>Ctrl</code>+<code>Y</code> come forward, and there is one history for the whole editor: a change made on the drawn document can be taken back on the source, and the other way round. A <code>contenteditable</code> that refuses every input never gets an entry on the browser&#39;s own stack, so both surfaces put their changes on Mawy&#39;s instead. A run of typing is one step rather than one per keystroke — a change carries on from the one before it while it is the same kind, in the same place, within a moment of it, and a syllable being composed counts as more of the same typing because a Korean keyboard rewrites what it wrote on every jamo. A line ending closes the run behind it.</li><li><strong>A status bar</strong> counting position, selection, lines, words, characters and bytes. Words add every Han, hiragana and katakana character to the space-separated count; characters are code points; size is UTF-8 bytes.</li><li><strong>Code blocks are coloured by whatever <code>highlight</code> is given</strong>, and by nothing at all by default. A highlighter is the largest thing a Markdown renderer can be made to carry and most documents have nothing in them to colour, so the prop takes a <em>function</em> as readily as a highlighter: <code>() =&gt; import(&#39;mawy-react/highlight&#39;).then((module) =&gt; module.mawyHighlighter)</code> fetches one the first time a document with a language on a fence is actually drawn, and never otherwise. What comes back is <strong>tokens rather than markup</strong> — text and a name from a closed list of thirteen — and this package decides what element each becomes, so nothing reaches the page as a string of HTML and a highlighter cannot put a <code>&lt;script&gt;</code> in a document by being wrong. The tokens are checked against the code they claim to be and a block that does not add up is drawn plain. Each coloured piece says where it came from, like everything else the renderer draws.</li><li><strong><code>mawy-react/highlight</code></strong>, a highlighter of our own in an entry point of its own, so an application that never mentions it never ships it. It knows the languages a document usually shows — <code>js</code>, <code>ts</code>, <code>jsx</code>, <code>tsx</code>, <code>json</code>, <code>html</code>, <code>xml</code>, <code>css</code>, <code>bash</code>, <code>python</code>, <code>yaml</code>, <code>sql</code>, <code>go</code>, <code>rust</code>, <code>java</code>, <code>c</code>, <code>cpp</code> and the other names each answers to — and it is approximate on purpose, in the same way and for the same reasons as the one that colours the source surface.</li><li><strong><code>MawyViewer</code></strong> — a Markdown document, rendered and not editable. The document becomes React elements rather than a string of HTML, so there is no <code>innerHTML</code> between the Markdown and the page.</li><li><strong>The Markdown parser.</strong> CommonMark — headings, paragraphs, fenced and indented code, quotations, nested lists, thematic breaks, HTML blocks, emphasis by the specification&#39;s own delimiter-stack rules, links and images including reference definitions resolved from anywhere in the file, autolinks, hard breaks, character references and escapes — plus GitHub&#39;s additions: tables with per-column alignment, task lists, <code>~~strikethrough~~</code>, bare URLs and e-mail addresses, footnotes, and the five alert kinds. <code>parse</code> carries <code>gfm</code>, <code>breaks</code> and <code>definitionLists</code>.</li><li><strong>Footnotes.</strong> A <code>[^label]</code> in a sentence is a number, and the note it points at is drawn under the document with a link back to where it was mentioned. Numbered by the order they are first mentioned rather than the order they are written in, because that is the order a reader meets them; a note nobody mentions is not drawn at all, the way a link reference definition nobody used is nowhere either; and a <code>[^label]</code> with nothing to point at stays as the characters it was written with. A note may be a whole run of blocks, and where in the file it was written makes no difference — the parser lifts it out of the flow, so <code>MdDocument</code> hands the footnotes back separately and whatever draws a document draws them after it.</li><li><strong>Definition lists</strong>, which is the one thing here GitHub does not read. PHP Markdown Extra&#39;s syntax, which is the one everybody who writes these uses: a line of text, then a line opening with a colon and a space. The space is not decoration — <code>:warning:</code> under a sentence is an emoji shortcode in a great many documents, and without it every one of them would turn the sentence above into a term. Several terms may share a meaning, several meanings may share a term, a meaning may be a whole run of blocks, and a blank line spaces the list out the way it does a bullet list. <code>parse</code> gains <code>definitionLists</code> to turn it off for a document that has to mean exactly what it would mean on GitHub.</li><li><strong>Every node knows where it came from.</strong> A parsed node carries the range of the source it was read out of — through however many containers it was nested in, past the <code>&gt;</code> a quotation puts on each line, the indent of a list item and the pipes around a table cell — and a child&#39;s range always sits inside its parent&#39;s. Offsets are counted in the document as it was handed over rather than as the parser tidied it, so a file with Windows line endings, a byte order mark or a tab where an indent should be answers in its own characters. They are what the preview scrolling in step with the source is built on, and what an edit made in the drawn document and written back to the Markdown is built on.</li><li><strong>Every element says where it came from.</strong> The viewer draws each one with <code>data-mawy-range=&quot;start,end&quot;</code> — the offsets in the Markdown it was given of that piece&#39;s first character and of the one after its last. Blocks, list items, table rows and cells, the inline elements inside them — emphasis, links, code spans, images — and each coloured piece of a highlighted code block. A code block says it twice — the box around it for the fences, the info string and the indent, and the <code>code</code> element inside for the code itself, which is the part a caret can be in and is a place even when there is nothing between the fences at all. The offsets index the string that was passed, so <code>value.slice(start, end)</code> is the Markdown behind whatever was clicked. Text carries none, having no attributes to carry one in, and needs none: a run of text is bounded by the elements on either side of it, which is enough to find it in the source between them.</li><li><strong>A toolbar for how the document is set</strong>, not for what it says: typeface, text size, line height, letter spacing, column width, light or dark, an outline of the headings, the source to the clipboard, and a file picker. <code>toolbar</code> takes the controls to draw and the order to draw them in, or <code>false</code> for none. It is a real <code>toolbar</code> — one tab stop, arrow keys inside.</li><li><strong>A file picker where a document would be.</strong> With no <code>value</code>, the viewer is the thing you drop a <code>.md</code> file on. <code>onValueChange</code> reports the text and the <code>File</code> it came from, controlled or not.</li><li><strong>An outline panel</strong>, built from the same slugs the renderer gives the headings, tracking where the reader is.</li><li><strong>Light and dark</strong>, through <code>colorScheme</code> — <code>&#39;system&#39;</code> by default, and following <code>prefers-color-scheme</code> only for that value.</li><li><strong>A typeface list, and web fonts behind a prop.</strong> The toolbar offers whatever <code>fonts</code> gives it. The default is three roles the reader&#39;s machine already has, and it fetches nothing; <code>MAWY_WEB_FONTS</code> is a catalogue of thirteen families under the SIL Open Font License — eight Latin, five Korean — that an application opts into by passing them. Nothing is requested until a font is chosen or the typeface menu is opened, each name in that menu is drawn in its own face, and every stylesheet is fetched once per page.</li><li><strong>The stylesheet declares its tokens on <code>.mawy-root</code></strong> rather than on <code>:root</code>, so a viewer can be dark inside a light page and the library never writes to the document element. Every rule the library ships is scoped under it, which is what keeps a host page&#39;s own <code>article h2</code> from restyling a document.</li><li>Types: <code>MawyTypography</code>, <code>MawyFontFamily</code>, <code>MawyFont</code>, <code>MawyMeasure</code>, <code>MawyParseOptions</code>, <code>MawyHtmlPolicy</code>, <code>MawyImageUpload</code>, <code>MawyImageSource</code>, <code>MawyHighlight</code>, <code>MawyHighlighter</code>, <code>MawyCodeToken</code>, <code>MawyCodeTokenKind</code>, <code>MawyViewerToolbarItem</code>, <code>MawyViewerToolbarOption</code>, <code>MawyEditorToolbarItem</code>, <code>MawyEditorToolbarOption</code>, <code>MawyEditorStatusItem</code>, <code>MawyEditorStatusOption</code>. Values: <code>MAWY_SYSTEM_FONTS</code>, <code>MAWY_WEB_FONTS</code>.</li></ul><h3 id="security-1" tabindex="-1">Security <a class="header-anchor" href="#security-1" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li><strong>Every URL a document names is checked against a scheme allowlist</strong>, in Markdown as much as in HTML — <code>[click](javascript:…)</code> is refused under every setting of <code>html</code>, and is drawn as the words the author wrote rather than as a link that does nothing. <code>data:</code> is allowed for images, and only for media types a browser draws.</li><li><strong>Raw HTML inside a document is inert by default.</strong> <code>html</code> chooses: <code>&#39;escape&#39;</code> shows the markup as text, <code>&#39;sanitize&#39;</code> draws it through an allowlist of elements, attributes and URL schemes parsed with <code>DOMParser</code>, and <code>&#39;raw&#39;</code> hands the caller the consequences.</li></ul><h3 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h3><ul><li>Added <a href="https://lucide.dev" target="_blank" rel="noreferrer"><code>lucide-react</code></a> (ISC), the package&#39;s first and only runtime dependency, for the toolbar&#39;s icons.</li></ul>',27)])])}const g=t(i,[["render",s]]);export{w as __pageData,g as default};
